-- Known issue: For aggregated scene_type (Platform / S&R / RCMD), order_cnt may be double counted
--              when original, source1, source2 scene_type values are different but are included in the same aggregated scene_type.
--              For aggregated card_type, order_cnt may be double counted
--              when original, source1, source2 target_type are different but are included in the same aggregated card_type.
--              BI thinks the gap is acceptable so it's not addressed, and we follow the same logic as them.
--              Special Logic is used for scene_type = Platform and card_type = __ALL__ because the order_cnt difference is > 25%

create temporary view user_item_raw_${grass_region_without_quote} as
select
    user_id
    ,case when is_ads = true then 'true' else 'false' end as is_ads
    ,if(split(feature_detail, '-')[2] is not null, split(feature_detail, '-')[2], split(feature_detail, '-')[1]) as target_type
    ,if(split(source1_feature_detail, '-')[2] is not null, split(source1_feature_detail, '-')[2], split(source1_feature_detail, '-')[1]) as source1_target_type
    ,if(split(source2_feature_detail, '-')[2] is not null, split(source2_feature_detail, '-')[2], split(source2_feature_detail, '-')[1]) as source2_target_type
    ,case
        when
            array_contains(scenario_tags, 'dpm module Global Search business line Search')
            or array_contains(scenario_tags, 'dpm module Image Search business line Search')
        then 'Search'
        when array_contains(scenario_tags, 'dpm module Daily Discover business line Homepage') then 'DD'
        when exists(scenario_tags, x -> x like 'dpm reporting object you may also like % business line Rcmd') then 'YMAL'
        when exists(scenario_tags, x -> x like 'dpm reporting object post purchase % business line Rcmd') then 'PP'
        else 'Others'
    end as scene_type
    ,case
        when
            array_contains(source1_scenario_tags, 'dpm module Global Search business line Search')
            or array_contains(source1_scenario_tags, 'dpm module Image Search business line Search')
        then 'Search'
        when array_contains(source1_scenario_tags, 'dpm module Daily Discover business line Homepage') then 'DD'
        when exists(source1_scenario_tags, x -> x like 'dpm reporting object you may also like % business line Rcmd') then 'YMAL'
        when exists(source1_scenario_tags, x -> x like 'dpm reporting object post purchase % business line Rcmd') then 'PP'
        else 'Others'
    end as source1_scene_type
    ,case
        when
            array_contains(source2_scenario_tags, 'dpm module Global Search business line Search')
            or array_contains(source2_scenario_tags, 'dpm module Image Search business line Search')
        then 'Search'
        when array_contains(source2_scenario_tags, 'dpm module Daily Discover business line Homepage') then 'DD'
        when exists(source2_scenario_tags, x -> x like 'dpm reporting object you may also like % business line Rcmd') then 'YMAL'
        when exists(source2_scenario_tags, x -> x like 'dpm reporting object post purchase % business line Rcmd') then 'PP'
        else 'Others'
    end as source2_scene_type
    ,omni_scenario_imp_cnt
    ,omni_scenario_click_cnt
    ,order_cnt
    ,operation
    ,item_llm_cluster_id
from
    srdi_mart.dwm_sr_data_warehouse_platform_user_item
where
    grass_region in (${grass_region})
    and local_date between date_sub(${local_date}, ${date_offset}) and ${local_date}
    and operation in ('omni_impression', 'omni_click', 'order')
    and user_id > 0
    and item_id > 0
    and (omni_scenario_imp_cnt > 0 or omni_scenario_click_cnt > 0 or order_cnt > 0)
;

--sql_divide_splitter--
create temporary view user_item_processed_${grass_region_without_quote} as
select
    user_id
    ,is_ads
    ,case
        when target_type in ('item', 'item_mix_feed_card') then 'item + mixfeed'
        when target_type = 'video' then 'video'
        when coalesce(target_type, '') = '' then null
        else 'others'
     end as card_type
    ,case
        when source1_target_type in ('item', 'item_mix_feed_card') then 'item + mixfeed'
        when source1_target_type = 'video' then 'video'
        when coalesce(source1_target_type, '') = '' then null
        else 'others'
     end as source1_card_type
    ,case
        when source2_target_type in ('item', 'item_mix_feed_card') then 'item + mixfeed'
        when source2_target_type = 'video' then 'video'
        when coalesce(source2_target_type, '') = '' then null
        else 'others'
     end as source2_card_type
    ,scene_type
    ,source1_scene_type
    ,source2_scene_type
    ,omni_scenario_imp_cnt
    ,omni_scenario_click_cnt
    ,order_cnt
    ,operation
    ,item_llm_cluster_id
from
    user_item_raw_${grass_region_without_quote}
;

--sql_divide_splitter--
create temporary view user_item_union_${grass_region_without_quote} as
select
    user_id
    ,is_ads
    ,card_type
    ,scene_type
    ,omni_scenario_imp_cnt
    ,omni_scenario_click_cnt
    ,order_cnt
    ,item_llm_cluster_id
from
    user_item_processed_${grass_region_without_quote}

union all
select
    user_id
    ,is_ads
    ,source1_card_type as card_type
    ,source1_scene_type as scene_type
    ,0 as omni_scenario_imp_cnt
    ,0 as omni_scenario_click_cnt
    ,order_cnt
    ,item_llm_cluster_id
from
    user_item_processed_${grass_region_without_quote}
where
    operation = 'order'
    and source1_card_type is not null
    and concat_ws(' ', source1_scene_type, source1_card_type) != concat_ws(' ', scene_type, card_type)

union all
select
    user_id
    ,is_ads
    ,source2_card_type as card_type
    ,source2_scene_type as scene_type
    ,0 as omni_scenario_imp_cnt
    ,0 as omni_scenario_click_cnt
    ,order_cnt
    ,item_llm_cluster_id
from
    user_item_processed_${grass_region_without_quote}
where
    operation = 'order'
    and source2_card_type is not null
    and concat_ws(' ', source2_scene_type, source2_card_type) != concat_ws(' ', scene_type, card_type)
    and concat_ws(' ', source2_scene_type, source2_card_type) != concat_ws(' ', source1_scene_type, source1_card_type)
;

--sql_divide_splitter--
create temporary view user_cluster_agg_${grass_region_without_quote} as
select
    user_id
    ,is_ads
    ,item_llm_cluster_id
    ,'__ALL__' as card_type
    ,scene_type
    ,sum(omni_scenario_imp_cnt) as omni_scenario_imp_cnt
    ,sum(omni_scenario_click_cnt) as omni_scenario_click_cnt
    ,sum(order_cnt) as order_cnt
from
    user_item_union_${grass_region_without_quote}
group by 1, 2, 3, 5

union all
select
    user_id
    ,is_ads
    ,item_llm_cluster_id
    ,card_type
    ,scene_type
    ,sum(omni_scenario_imp_cnt) as omni_scenario_imp_cnt
    ,sum(omni_scenario_click_cnt) as omni_scenario_click_cnt
    ,sum(order_cnt) as order_cnt
from
    user_item_union_${grass_region_without_quote}
where
    card_type in ('item + mixfeed', 'video')
group by 1, 2, 3, 4, 5

union all
select
    user_id
    ,is_ads
    ,item_llm_cluster_id
    ,if(card_type in ('item + mixfeed', 'video'), 'item + mixfeed + video', 'others') as card_type
    ,scene_type
    ,sum(omni_scenario_imp_cnt) as omni_scenario_imp_cnt
    ,sum(omni_scenario_click_cnt) as omni_scenario_click_cnt
    ,sum(order_cnt) as order_cnt
from
    user_item_union_${grass_region_without_quote}
group by 1, 2, 3, 4, 5

union all
select
    user_id
    ,is_ads
    ,case
        when item_llm_cluster_id is null then null
        when card_type = 'video' then concat('v#', item_llm_cluster_id)
        else item_llm_cluster_id
    end as item_llm_cluster_id
    ,'item + mixfeed + video - no dedup' as card_type
    ,scene_type
    ,sum(omni_scenario_imp_cnt) as omni_scenario_imp_cnt
    ,sum(omni_scenario_click_cnt) as omni_scenario_click_cnt
    ,sum(order_cnt) as order_cnt
from
    user_item_union_${grass_region_without_quote}
where
    card_type in ('item + mixfeed', 'video')
    and scene_type in ('DD', 'PP')
group by 1, 2, 3, 4, 5
;

