create temporary view cubed_data_${grass_region_without_quote} as
select
    user_id
    ,coalesce(is_ads, '__ALL__') as is_ads
    ,'__ALL__' as card_type
    ,'Platform' as scene_type
    ,sum(omni_scenario_imp_cnt)   as omni_scenario_imp_cnt
    ,sum(omni_scenario_click_cnt) as omni_scenario_click_cnt
    ,sum(order_cnt) as order_cnt

    ,count(distinct case when omni_scenario_imp_cnt > 0 then item_llm_cluster_id else null end) as imp_llm_cat_count_per_uu
    ,count(distinct case when omni_scenario_click_cnt > 0 then item_llm_cluster_id else null end) as click_llm_cat_count_per_uu
    ,count(distinct case when order_cnt > 0 then item_llm_cluster_id else null end) as order_llm_cat_count_per_uu
from
    user_item_raw_${grass_region_without_quote} -- without union of source 1 & source 2
group by
    user_id
    ,cube(is_ads)
    ,card_type

union all
select
    user_id
    ,coalesce(is_ads, '__ALL__') as is_ads
    ,card_type
    ,'Platform' as scene_type
    ,sum(omni_scenario_imp_cnt)   as omni_scenario_imp_cnt
    ,sum(omni_scenario_click_cnt) as omni_scenario_click_cnt
    ,sum(order_cnt) as order_cnt

    ,count(distinct case when omni_scenario_imp_cnt > 0 then item_llm_cluster_id else null end) as imp_llm_cat_count_per_uu
    ,count(distinct case when omni_scenario_click_cnt > 0 then item_llm_cluster_id else null end) as click_llm_cat_count_per_uu
    ,count(distinct case when order_cnt > 0 then item_llm_cluster_id else null end) as order_llm_cat_count_per_uu
from
    user_cluster_agg_${grass_region_without_quote}
where
    card_type not in ('__ALL__', 'item + mixfeed + video - no dedup')
group by
    user_id
    ,cube(is_ads)
    ,card_type

union all
select
    user_id
    ,coalesce(is_ads, '__ALL__') as is_ads
    ,card_type
    ,'S&R' as scene_type
    ,sum(omni_scenario_imp_cnt)   as omni_scenario_imp_cnt
    ,sum(omni_scenario_click_cnt) as omni_scenario_click_cnt
    ,sum(order_cnt) as order_cnt

    ,count(distinct case when omni_scenario_imp_cnt > 0 then item_llm_cluster_id else null end) as imp_llm_cat_count_per_uu
    ,count(distinct case when omni_scenario_click_cnt > 0 then item_llm_cluster_id else null end) as click_llm_cat_count_per_uu
    ,count(distinct case when order_cnt > 0 then item_llm_cluster_id else null end) as order_llm_cat_count_per_uu
from
    user_cluster_agg_${grass_region_without_quote}
where
    scene_type in ('DD', 'PP', 'Search', 'YMAL')
    and card_type != 'item + mixfeed + video - no dedup'
group by
    user_id
    ,cube(is_ads)
    ,card_type


union all
select
    user_id
    ,coalesce(is_ads, '__ALL__') as is_ads
    ,card_type
    ,scene_type
    ,sum(omni_scenario_imp_cnt)   as omni_scenario_imp_cnt
    ,sum(omni_scenario_click_cnt) as omni_scenario_click_cnt
    ,sum(order_cnt) as order_cnt

    ,count(distinct case when omni_scenario_imp_cnt > 0 then item_llm_cluster_id else null end) as imp_llm_cat_count_per_uu
    ,count(distinct case when omni_scenario_click_cnt > 0 then item_llm_cluster_id else null end) as click_llm_cat_count_per_uu
    ,count(distinct case when order_cnt > 0 then item_llm_cluster_id else null end) as order_llm_cat_count_per_uu
from
    user_cluster_agg_${grass_region_without_quote}
where
    scene_type in ('DD', 'PP', 'YMAL', 'Search', 'Others')
group by
    user_id
    ,cube(is_ads)
    ,card_type
    ,scene_type

union all
select
    user_id
    ,coalesce(is_ads, '__ALL__') as is_ads
    ,card_type
    ,'RCMD' as scene_type
    ,sum(omni_scenario_imp_cnt)   as omni_scenario_imp_cnt
    ,sum(omni_scenario_click_cnt) as omni_scenario_click_cnt
    ,sum(order_cnt) as order_cnt

    ,count(distinct case when omni_scenario_imp_cnt > 0 then item_llm_cluster_id else null end) as imp_llm_cat_count_per_uu
    ,count(distinct case when omni_scenario_click_cnt > 0 then item_llm_cluster_id else null end) as click_llm_cat_count_per_uu
    ,count(distinct case when order_cnt > 0 then item_llm_cluster_id else null end) as order_llm_cat_count_per_uu
from
    user_cluster_agg_${grass_region_without_quote}
where
    scene_type in ('DD', 'PP', 'YMAL')
    and card_type != 'item + mixfeed + video - no dedup'
