    ,cube(is_ads)
    ,card_type
;

--sql_divide_splitter--
insert overwrite table ${schema}.dws_sr_data_warehouse_platform_scenario_card_level_diversity_nd
partition (grass_region = ${grass_region}, local_date = ${local_date}, num_day)
select
    scene_type
    ,card_type
    ,is_ads

    ,sum(omni_scenario_imp_cnt)   as imp_cnt
    ,sum(omni_scenario_click_cnt) as click_cnt
    ,sum(order_cnt) as order_cnt

    ,sum(if(omni_scenario_imp_cnt > 0, 1, 0)) as imp_uu
    ,sum(if(omni_scenario_click_cnt > 0, 1, 0)) as click_uu
    ,sum(if(order_cnt > 0, 1, 0)) as order_uu

    ,sum(imp_llm_cat_count_per_uu) as imp_llm_cat_cnt
    ,sum(click_llm_cat_count_per_uu) as click_llm_cat_cnt
    ,sum(order_llm_cat_count_per_uu) as order_llm_cat_cnt

    ,${date_offset} + 1 as num_day
from
    cubed_data_${grass_region_without_quote}
group by scene_type, card_type, is_ads;
